import json
from itertools import permutations

def solve():
    houses = [0, 1, 2, 3, 4]  # 0-based indices for houses 1..5

    Names = ["Peter", "Alice", "Eric", "Bob", "Arnold"]
    Birthdays = ["april", "feb", "mar", "jan", "sept"]
    Cigars = ["pall mall", "prince", "dunhill", "blends", "blue master"]
    Drinks = ["water", "coffee", "tea", "milk", "root beer"]

    solutions = []

    # Helper for "exactly one house between" meaning distance of 2
    def one_between(i, j):
        return abs(i - j) == 2

    for names_perm in permutations(Names):
        # 13. Eric is in the third house (index 2)
        if names_perm[2] != "Eric":
            continue

        idx = {name: names_perm.index(name) for name in Names}

        # 5. Peter is somewhere to the right of the root beer lover (root beer lover is Eric) -> Peter right of Eric
        if idx["Peter"] <= idx["Eric"]:
            continue

        # 9. Arnold is directly left of Peter
        if idx["Arnold"] != idx["Peter"] - 1:
            continue

        for bday_perm in permutations(Birthdays):
            # 8. February is in the second house (index 1)
            if bday_perm[1] != "feb":
                continue

            # 3. The person whose birthday is in April is Bob
            if bday_perm[idx["Bob"]] != "april":
                continue

            # 6. One house between January and Peter
            if not one_between(bday_perm.index("jan"), idx["Peter"]):
                continue

            for cigar_perm in permutations(Cigars):
                # 2. Pall Mall is in the third house (index 2)
                if cigar_perm[2] != "pall mall":
                    continue

                # 7. Blends smoker has Feb birthday; and 8 puts Feb at house 2 -> house 2 is Blends
                if cigar_perm[1] != "blends":
                    continue

                # 4. Dunhill smoker has March birthday (same house)
                if cigar_perm.index("dunhill") != bday_perm.index("mar"):
                    continue

                for drink_perm in permutations(Drinks):
                    # 1. The root beer lover is Eric
                    if drink_perm[idx["Eric"]] != "root beer":
                        continue

                    # 11. Blue Master smoker is the coffee drinker
                    if cigar_perm.index("blue master") != drink_perm.index("coffee"):
                        continue

                    # 12. One house between tea and coffee
                    if not one_between(drink_perm.index("tea"), drink_perm.index("coffee")):
                        continue

                    # 10. Milk is not in the fifth house (index 4)
                    if drink_perm[4] == "milk":
                        continue

                    # All constraints satisfied; record solution
                    solutions.append((names_perm, bday_perm, cigar_perm, drink_perm))

    # Expect exactly one solution
    if not solutions:
        raise RuntimeError("No solution found")
    if len(solutions) > 1:
        # If multiple, choose the first but this puzzle should yield a unique solution
        pass

    names_sol, bday_sol, cigar_sol, drink_sol = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "Birthday", "Cigar", "Drink"],
            "rows": []
        }
    }

    for i in range(5):
        row = [
            str(i + 1),
            names_sol[i],
            bday_sol[i],
            cigar_sol[i],
            drink_sol[i]
        ]
        output["solution"]["rows"].append(row)

    print(json.dumps(output, ensure_ascii=False))



if __name__ == "__main__":
    solve()
